def main():
    out = os.path.join(os.path.dirname(__file__), "..", "..", "plan", "03-evidence-register.csv")
    extra = os.path.join(os.path.dirname(__file__), "register_extra_rows.py")
    rows = list(ROWS)
    if os.path.exists(extra):
        ns = {"A": A}
        exec(open(extra, encoding="utf-8").read(), ns)
        # OVERRIDES update earlier rows after later research; the note records why.
        idx = {"id": 0, "topic": 1, "item": 2, "verbatim": 3, "class": 4, "source": 5, "location": 6,
               "published": 7, "accessed": 8, "confidence": 9, "conflicts": 10, "public_status": 11, "notes": 12}
        for i, r in enumerate(rows):
            ov = ns.get("OVERRIDES", {}).get(r[0])
            if ov:
                r = list(r)
                for k, v in ov.items():
                    r[idx[k]] = v
                rows[i] = tuple(r)
        rows += ns.get("ROWS", [])
    cols = ["id", "topic", "item", "verbatim", "class", "source", "location", "published", "accessed",
            "confidence", "conflicts", "public_status", "notes"]
    with open(out, "w", newline="", encoding="utf-8") as fh:
        w = csv.writer(fh)
        w.writerow(cols)
        for r in rows:
            r = list(r)
            r[5] = SRC.get(r[5], r[5])
            w.writerow(r)
    print(f"wrote {len(rows)} rows to {os.path.normpath(out)}")


if __name__ == "__main__":
    main()
